  handlePermissionState() {
    navigator.permissions.query({ name: "microphone" }).then((queryResults) => {
      console.log(queryResults?.state, "queryResults")
      this.setState({
        microphonePermissionState: queryResults?.state
      })
      this.getAvailableAudioDevices().then((devices) => {
        console.log({ devices }, "devices")
        this.setState({
          availableDevices: devices,
          selectedAudioDevice: devices.find((device) => device.id === "default")?.id
        })
      })
      queryResults.onChange = function (onChangeResult) {
        if (onChangeResult.target) {
          this.microphonePermissionState = ((onChangeResult?.target)?.state)
        }
      }
    })
  };

  getAvailableAudioDevices() {
    return new Promise((resolve) => {
      navigator.mediaDevices.enumerateDevices().then((devices) => {
        const availableDevices = devices?.filter((d) => d?.kind === "audiooutput")
          .map((d) => {
            return { id: d.deviceId, name: d.label };
          });
        resolve(availableDevices)
      });
    })
  };

