  handleSlider(event) {
    if (!this.state.recordingOn) {
      this.videoRef.current.currentTime = this.state.playingAt;
      if (this.state.isloopStart == false) {
        this.setState({
          time: true,
          selectTime: event.target.value
        })
        if (this.state.time === true) {
          const intervals = setInterval(() => {
            const value = parseInt(this.masterGainNode[0]?.context?.currentTime * this.state.incPitch);
            const val = parseInt(this.state.selectTime);
            const data = value + val
            this.setState({
              playingAt: data,
            })
            if (this.state.playingAt > this.inputAudio[0].data.duration) {
              this.setState({ playButtonNextAction: 'Resume' });
              clearInterval(intervals);
            }
            else if (this.state.isloopStart == true || this.state.time == false) {
              clearInterval(intervals);
            }
          }, 1000)
        }
      }
    }
  };

